    flags={'--list','-l','--list-all','-a','--json','-j','--dry','-n','--silent','-s','--verbose','-v','--force','-f','--parallel','-p','--status','--summary','-x','--exit-code','--disable-fuzzy','--color','-c','--no-status','--nested'}
    valued={'--dir','-d','--taskfile','-t','--concurrency','-C','--output','-o','--sort'}
    skip=False
    for a in args:
        if skip:skip=False;continue
        if a in valued:skip=True;continue
        if a in flags or a.startswith('--'):continue
        names.append(a)
    tasks=cfg.get('tasks') or {}
    if '--summary' in argv:
        ix=argv.index('--summary'); name=argv[ix+1] if ix+1<len(argv) else (names[0] if names else 'default')
        return show_summary(cfg,name,str(path),cwd)
    if '--status' in argv:
        name=names[0] if names else (argv[argv.index('--status')+1] if argv.index('--status')+1<len(argv) else 'default')
        return check_status(cfg,name,cwd)
    if '--list' in argv or '-l' in argv or '--list-all' in argv or '-a' in argv:
        all_= '--list-all' in argv or '-a' in argv
        entries=[(k,v if isinstance(v,dict) else {}) for k,v in tasks.items() if all_ or (isinstance(v,dict) and v.get('desc'))]
        entries.sort(key=lambda p:p[0])
        filepath=str(pathlib.Path(path).resolve())
        if '--json' in argv or '-j' in argv: print(json.dumps({'tasks':[{'name':k,'task':k,'desc':v.get('desc',''),'summary':v.get('summary',''),'aliases':v.get('aliases',[]),'up_to_date':False,'location':{'line':1,'column':3,'taskfile':filepath}} for k,v in entries],'location':filepath},indent=2))
        elif silent:
            for k,v in entries: print(k)
        elif entries:
            print('task: Available tasks for this project:')
            for k,v in entries:print(f'* {k}:       {v.get("desc","")}')
        else:print('task: No tasks with description available. Try --list-all to list all tasks')
        return 0
    return run_tasks(cfg,names,cwd=root,dry=dry,silent=silent,force='--force' in argv or '-f' in argv,cli_args=cli_args,exit_code='--exit-code' in argv or '-x' in argv)

if __name__=='__main__':sys.exit(main(sys.argv[1:]))
