"""Task execution helpers."""
import os, subprocess, sys
from templating import render, resolve_vars


def _subst(s, values):
    return render(s, values)


def run_tasks(config, names, *, cwd=None, dry=False, silent=False, force=False, cli_args='', cli_vars=None, exit_code=False):
    """Run task definitions from normalized Taskfile dictionary. Return exit status."""
    tasks=config.get('tasks') or {}
    cwd=cwd or os.getcwd()
    values=resolve_vars(config.get('vars') or {}, env=os.environ)
    values.update(cli_vars or {})
    values['CLI_ARGS']=cli_args
    active=set(); done=set()
    if not names: names=['default']
    def run(name, overrides=None):
        if name in done: return 0
        if name in active:
            print('task: Task called too many times (recursion limit)',file=sys.stderr); return 204
        task=tasks.get(name)
        if task is None:
            print(f'task: Task "{name}" does not exist',file=sys.stderr); return 200
        if isinstance(task,str): task={'cmds':[task]}
        elif isinstance(task,list): task={'cmds':task}
        task=task or {}; active.add(name)
        local_values=dict(values)
        local_values.update(overrides or {})
        task_env=dict(config.get('env') or {})
        task_env.update(task.get('env') or {})
        child_env=os.environ.copy()
        for key, value in task_env.items():
            if isinstance(value,dict) and 'sh' in value:
                try: value=subprocess.check_output(value['sh'],shell=True,cwd=cwd,env=child_env,text=True).rstrip('\n')
                except Exception: value=''
            resolved=_subst(value, local_values)
            child_env[str(key)]=str(resolved)
            local_values[str(key)]=resolved
        for key, value in (task.get('vars') or {}).items():
            if isinstance(value, dict) and 'sh' in value:
                try: value=subprocess.check_output(value['sh'],shell=True,cwd=cwd,env=child_env,text=True).rstrip('\n')
                except Exception: value=''
            elif isinstance(value, dict) and 'ref' in value:
                value=render('{{'+str(value['ref'])+'}}',local_values)
            local_values[key]=_subst(value, local_values)
        deps=task.get('deps', []) or []
        if isinstance(deps,str): deps=[deps]
        for dep in reversed(deps):
            dep_vars={}
            if isinstance(dep,dict):
                dep_vars=dep.get('vars') or {}
                dep=dep.get('task','')
            if isinstance(dep_vars,dict):
                dep_vars={str(k):_subst(v,local_values) for k,v in dep_vars.items()}
            if dep and (rc:=run(str(dep),dep_vars)): active.remove(name); return rc
        task_cmds=task.get('cmds',[]) or []
        if not task_cmds and task.get('cmd'):
            task_cmds=[task['cmd']]
        task_env = child_env.copy()
        task_dir = _subst(task.get('dir') or cwd, local_values)
        if not os.path.isabs(task_dir):
            task_dir = os.path.join(cwd, task_dir)
        for item in task_cmds:
            if isinstance(item,str): cmd=item; task_silent=False
            elif isinstance(item,dict):
                if item.get('task'):
                    ref=item.get('task')
                    ref_vars=item.get('vars') or {}
                    if isinstance(ref_vars,dict):
                        ref_vars={str(k):_subst(v,local_values) for k,v in ref_vars.items()}
                    if (rc:=run(str(ref),ref_vars)):
                        active.remove(name); return rc
                    continue
                cmd=item.get('cmd',''); task_silent=item.get('silent',False)
